import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_gcd(N, A):
    total_gcd = reduce(gcd, A)
    if total_gcd > 1:
        return total_gcd

    max_gcd_value = 1
    for i in range(N):
        current_gcd = reduce(gcd, A[:i] + A[i+1:])
        for j in range(2, int(math.sqrt(A[i])) + 1):
            if A[i] % j == 0:
                candidate_gcd = gcd(current_gcd, j)
                if candidate_gcd > max_gcd_value:
                    max_gcd_value = candidate_gcd
                candidate_gcd = gcd(current_gcd, A[i] // j)
                if candidate_gcd > max_gcd_value:
                    max_gcd_value = candidate_gcd

    return max_gcd_value

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    A = list(map(int, data[1:]))

    result = max_gcd(N, A)
    print(result)
